sys.path.insert(0,str(OLD_REPO/'automation/local_bridge_operator')) # Reuse native-verified quadratic gradients and no response basis.
from complex_quadratic import reference_gradients # Retain all twenty-seven integration points and their true reference volumes.
def errors(predicted,truth,weights): # Compare complete native tensors and accumulated plastic history using physical tensor norms.
    groups={'stress':slice(3,9),'peeq':slice(9,10),'raw_plastic_metric':slice(10,16),'material_backstress':slice(16,22)};result={} # Keep units and interpretation separate rather than mixing all state channels in one number.
    for name,channels in groups.items(): # Integrate every real steel IP over every supplied accepted time without a sampled spatial subset.
        actual=truth[...,channels];difference=predicted[...,channels]-actual;factor=np.array([1.,1.,1.,2.,2.,2.]) if actual.shape[-1]==6 else np.ones(1);error=float(np.sum(difference*difference*factor*weights[None,:,None]));denominator=float(np.sum(actual*actual*factor*weights[None,:,None]));result[name]={'reference_volume_weighted_relative_L2':float(np.sqrt(error/max(denominator,1.e-30))),'maximum_absolute':float(np.abs(difference).max())} # Count symmetric tensor shear components twice in the full Frobenius norm.
    return result # Relative error is a measured diagnostic and introduces no new posthoc acceptance threshold.
def main(): # Evaluate one exact observed fine path and a fixed bounded macro-substep sensitivity study.
    torch.set_num_threads(1);started=time.monotonic();root=Path(__file__).parent;directory=root/'native_increment_development/cases/v2_rebar_increment_dev_00';metadata=json.loads((directory/'metadata.json').read_text());receipt=json.loads((directory/'receipt.json').read_text());assert receipt['native_complete'] and receipt['row']['quality']=='VALID_CONVERGED';path=root/'v2_rebar_material_path_checks.json';assert not path.exists() # Keep completed diagnostics immutable and independent from formal neural model selection.
    for name,expected in receipt['files'].items(): assert sha(directory/name)==expected # Require every original native evidence object, including the immediate snapshot, to retain its expected identity.
    with np.load(directory/'fields.npz') as graph: conn=graph['elements'];steel=graph['materials']==1;nodes=int(graph['node_count']);xyz=graph['xyz'][:nodes];ip_count=graph['ip_entity_ids'].shape[1] # Load known geometry and quadrature only; derive all observed responses directly from original accepted DAT frames.
    steel_ids=np.where(steel)[0]+1;lookup={int(identity):index for index,identity in enumerate(steel_ids)};gradient,weights=reference_gradients(xyz,conn[steel],element_type='C3D20');weight=weights.ravel();times=[0.];Fs=[np.broadcast_to(np.eye(3),(len(weight),3,3)).copy()];truths=[np.zeros((len(weight),24))] # Start from the actual known undeformed, unplasticized physical state.
    for timestamp,frame in stream_dat(directory/'model.dat'): # Preserve every real intermediate finite-element deformation rather than fabricating a fine path from endpoint controls.
        u=np.zeros((nodes,3));u[frame['u'][:,0].astype(int)-1]=frame['u'][:,1:4];F=np.eye(3)+np.einsum('eai,eqaj->eqij',u[conn[steel]],gradient);truth=np.zeros((len(steel_ids),ip_count,24)) # Compute the complete steel deformation tensor at each original quadrature point.
        for row in frame['stress']: # Select native steel stress by exact element identity.
            if int(row[0]) in lookup: truth[lookup[int(row[0])],int(row[1])-1,3:9]=row[2:8] # Retain all physical stress components and their native shear convention.
        for row in frame['sdv']: truth[lookup[int(row[0])],int(row[1])-1,9:22]=row[2:15] # Keep all thirteen native material variables without reducing or averaging their local states.
        times.append(timestamp);Fs.append(F.reshape(-1,3,3));truths.append(truth.reshape(-1,24)) # Store one small material-only diagnostic path, not another large full finite-element text copy.
    times=np.array(times);Fs=np.array(Fs);truths=np.array(truths);assert len(times)==100 and times[-1]==24.;state=torch.zeros((len(weight),24),dtype=torch.float64);predicted=[state.numpy().copy()];fine_crossings=0 # The new native history has ninety-nine actual accepted material increments.
    for F in Fs[1:]: # Propagate predicted material state recursively from the known initial state along the supplied true deformation path.
        result=native_kinematic_increment(torch.tensor(F),state,metadata['params'][1]);state=result['state'];fine_crossings+=int(result['crossed_hardening_last_point'].sum());predicted.append(state.detach().numpy().copy()) # Never replace the preceding predicted material state with a native SDV during this history-rollout verification.
    predicted=np.array(predicted);macro=np.array([i for i,timestamp in enumerate(times) if abs(timestamp-round(timestamp))<1.e-9]);assert len(macro)==25;studies=[] # Identify only actual printed macro-stage endpoints, including time zero.
    for count in [1,2,4,8]: # Bound the interpolation study before looking at its errors; no additional native solve is launched.
        state=torch.zeros((len(weight),24),dtype=torch.float64);coarse=[state.numpy().copy()];crossings=0 # Start each explicitly different integration discretization from the same known initial material state.
        for previous_index,next_index in zip(macro[:-1],macro[1:]): # Approximate only the unobserved within-macro deformation by declared linear F interpolation.
            for substep in range(1,count+1): # Retain every local integration point while varying temporal discretization alone.
                fraction=substep/count;F=(1-fraction)*Fs[previous_index]+fraction*Fs[next_index];result=native_kinematic_increment(torch.tensor(F),state,metadata['params'][1]);state=result['state'];crossings+=int(result['crossed_hardening_last_point'].sum()) # This is a declared assumed deformation path, not an exact replay of native intermediate equilibria.
            coarse.append(state.detach().numpy().copy()) # Compare each predicted material macro endpoint with the actual original endpoint reference.
        studies.append({'substeps_per_macro_stage':count,'actual_material_update_count':24*count*len(weight),'observed_terminal_crossings':crossings,'errors':errors(np.array(coarse)[1:],truths[macro][1:],weight)}) # Report all fixed alternatives without selecting one from hidden evaluation data.
    path_error=[] # Quantify why increasing substeps does not reconstruct an absent nonlinear equilibrium path automatically.
    for previous_index,next_index in zip(macro[:-1],macro[1:]): # Compare the actual fine deformation to the macro-linear assumption on its native time grid.
        for i in range(previous_index+1,next_index): fraction=(times[i]-times[previous_index])/(times[next_index]-times[previous_index]);linear=(1-fraction)*Fs[previous_index]+fraction*Fs[next_index];path_error.append(float(np.max(np.abs(Fs[i]-linear)))) # Use complete tensor component differences at every native steel point.
    report={'status':'COMPLETED_BOUNDED_MATERIAL_PATH_DIAGNOSTIC','development_case':str(directory),'native_receipt_sha256':sha(directory/'receipt.json'),'source_sha256':sha(__file__),'increment_map_sha256':sha(root/'v2_rebar_constitutive_increment.py'),'fine_path':{'accepted_increments':99,'steel_IPs':len(weight),'total_material_updates':99*len(weight),'previous_native_SDV_used_after_initial':False,'actual_native_F_used_as_supplied_input':True,'terminal_crossings':fine_crossings,'all_accepted_time_errors':errors(predicted[1:],truths[1:],weight),'macro_endpoint_errors':errors(predicted[macro][1:],truths[macro][1:],weight)},'macro_linear_F_substeps':studies,'maximum_actual_fine_F_minus_macro_linear_F_component':max(path_error,default=0.),'scope':'Constitutive-history integration diagnostic only. Native F is a supplied observed input, so this is not a neural prediction or a displacement/equilibrium solve. Macro-linear F substeps are explicitly approximate; no formal25frame training contract or reference gate changes.','new_test_or_ood_truth_read':False,'elapsed_seconds':time.monotonic()-started};path.write_text(json.dumps(report,indent=2)+'\n');print(json.dumps(report,indent=2)) # Preserve every bounded comparison, including any lack of convergence to the actual native reference path.
if __name__=='__main__': main() # Execute only the already authorized development-history diagnostic.
